package com.loopers.interfaces.consumer
import org.apache.kafka.clients.consumer.KafkaConsumer;import org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.Test;import java.time.Duration
class KafkaPartitionExperimentTest{@Test fun rangeAssignorHasStableTwoPartitionThreeConsumerAssignment(){KafkaExperimentSupport().use{k->k.consumer("w6-assign","A").use{a->k.consumer("w6-assign","B").use{b->k.consumer("w6-assign","C").use{c->k.topic("orders-w6",2);a.subscribe(listOf("orders-w6"));repeat(20){a.poll(Duration.ofMillis(100))};b.subscribe(listOf("orders-w6"));repeat(30){a.poll(Duration.ofMillis(100));b.poll(Duration.ofMillis(100))};c.subscribe(listOf("orders-w6"));var last:List<List<Int>>?=null;var same=0;repeat(100){listOf(a,b,c).forEach{it.poll(Duration.ofMillis(100))};val now=listOf(a,b,c).map(::parts);same=if(now==last)same+1 else 0;last=now;if(same>=3)return@repeat};assertThat(parts(a)).containsExactly(0);assertThat(parts(b)).containsExactly(1);assertThat(parts(c)).isEmpty()}}}}};private fun parts(c:KafkaConsumer<String,String>)=c.assignment().map{it.partition()}.sorted()}
